function draftProblem(d){const problem=company.draftProblem(d)||company.referencesProblem(d);if(problem)return problem;if(!d.prompt?.trim()||d.prompt.length>3000)return '提示词须为 1–3000 字。';if(!Number.isInteger(+d.count)||+d.count<1||+d.count>6)return '生成数量须为 1–6 的整数。';if(!['1:1','3:4','9:16','16:9'].includes(d.ratio)||!(d.media==='video'?['1080P']:['1024 × 1024','2048 × 2048','4096 × 4096']).includes(d.quality))return '比例或清晰度与媒体不兼容。';if(d.media==='video'&&![6,12,15].includes(+d.duration))return '视频时长须为 6、12 或 15 秒。';if(!(d.media==='image'?['main','detail']:['video','clip']).includes(d.purpose))return '用途与媒体不兼容。';if(!task().products.includes(d.product))return '当前商品不属于本任务。';if(!['公司默认模型','高保真模型 · 演示','高保真图片模型 · 演示','标准视频模型 · 演示'].includes(d.model)||d.media==='image'&&d.model.includes('视频')||d.media==='video'&&d.model.includes('高保真'))return '模型与媒体不兼容。';for(const r of d.references||[]){const a=assetFromRef(r);if(r.startsWith('result:')&&(!canUse(a)||a.product!==d.product||d.media==='image'&&a.media!=='image'))return '本任务引用已失效或 SKU、媒体不匹配，请重新选择。';}return '';}
