function permissionForAction(action){
 if(['approve','reject','confirm-reject'].includes(action))return 'review';
 if(['adopt','delivery-choose','delivery-adopt','delivery-apply'].includes(action))return 'adopt';
 if(['export','download-package'].includes(action))return 'download';
 if(['confirm-reset','reset-demo'].includes(action)||/^company-(new-template|edit-template|save-draft|publish-preview|confirm-publish|toggle-template|confirm-toggle|member-)/.test(action))return 'manage';
 if(/^(requirements-|shots-)/.test(action)||['company-choose-template','company-template-preview','company-template-apply','company-reference','company-reference-apply'].includes(action))return 'create';
 if(/^creation-/.test(action)||['use-product','create-task','new-product','save-product','save-product-create','new-task','reset-draft','media','purpose','count','optimize','undo-prompt','optimize-intent','undo-intent','quick-prompt','apply-quick','apply-analysis','add-case','remove-case','remove-reference','upload','generate','confirm-generate','rework','node-generate','add-node','connect-source','connect-target','arrange','delivery-create'].includes(action))return 'create';
 if(/^batch-(add|copy|delete|confirm-delete|reset|confirm-reset|reset-field|preset|optimize|analyze|undo|submit|retry)$/.test(action))return 'create';
 return null;
}
