 document.body.style.overflow=batchSheet||$('#overlay-root .overlay')?'hidden':'';
 for(const el of $$('.batch-list-area,.batch-footer,.batch-topline,.studio-taskbar,.sidebar,.topbar'))el.inert=batchSheet;
 applyPermissions();
