 const mode=parameterMenu(`${icon(video?'video':'image')}<b>${video?'视频生成':'图片生成'}</b>`, `<span class="popover-title">创作类型</span>${[['image','image','图片生成','商品主图与详情素材'],['video','video','视频生成','商品展示与带货视频']].map(([id,ico,title,sub])=>`<button class="mode-option ${d.media===id?'selected':''}" data-action="media" data-id="${id}">${icon(ico)}<span><strong>${title}</strong><small>${sub}</small></span>${d.media===id?icon('check'):''}</button>`).join('')}`, 'media-menu');
 const model=parameterMenu(`${icon('box')}<span>${esc(d.model)}</span>`, `<span class="popover-title">生成模型</span>${fieldSelect('本次使用', 'model',['公司默认模型',video?'标准视频模型 · 演示':'高保真模型 · 演示'],d.model)}<p class="popover-note">仅应用到当前创作，保留公司默认标准。</p>`);
 const specs=parameterMenu(`${icon('expand')}<span>${d.ratio} · ${video?'1080P':parseInt(d.quality)/1024+'K'}</span>`, `<span class="popover-title">画面规格</span>${fieldSelect('画面比例','ratio',['1:1','3:4','9:16','16:9'],d.ratio)}${video?'<div class="parameter-field"><span>输出清晰度</span><strong>1080P</strong></div>':fieldSelect('输出清晰度','quality',[['1024 × 1024','1K'],['2048 × 2048','2K'],['4096 × 4096','4K']],d.quality)}`);
 const amount=parameterMenu(`${icon('layers')}<span>${d.count} ${video?'条':'张'}</span>`, `<span class="popover-title">生成数量</span>${fieldSelect(video?'视频条数':'图片张数','count',[1,2,3,4,5,6],d.count)}`);
 const duration=video?parameterMenu(`${icon('clock')}<span>${d.duration}s</span>`,`<span class="popover-title">视频时长</span>${fieldSelect('总时长','duration',[['6','6 秒'],['12','12 秒'],['15','15 秒']],d.duration)}<p class="popover-note">${d.purpose==='video'?'带货成片生成前须确认分镜。':'片段核对输入与时长后生成，不计成片交付。'}</p>`):'';
 const style=parameterMenu(`${icon('settings')}<span>创作设置</span>`,`<span class="popover-title">用途与风格</span>${fieldSelect('素材用途','purpose',video?[['video','带货成片 · 需确认分镜'],['clip','单段片段 · 不计成片交付']]:[['main','商品主图'],['detail','详情素材']],d.purpose)}<div class="parameter-field"><span>公司模板 · V${d.templateVersion||1}</span><strong>${esc(d.template)}</strong><button class="btn sm" data-action="company-choose-template" data-id="quick">选择已发布模板</button></div><p class="popover-note">当前：${purposeName(d.purpose)}</p><button class="text-button" data-action="reset-draft">${icon('refresh')}恢复公司默认配置</button>`,'style-menu');
