 if(draft().media==='video')return [`以${p.name}实拍为主体，镜头缓慢环绕展示全貌，光线自然，保持商品颜色、轮廓与结构一致。`,`围绕${p.name}实拍可见结构，镜头平稳推进至细节，不添加未知材质或卖点。`,`以${p.name}实拍为主体，先展示全貌，再过渡至可见细节，最后回到完整商品，平稳运镜，保持商品外观一致。`][index];
 return [basePrompt(p),`将${p.name}置于符合实际用途的${p.category==='美妆个护'?'日常梳妆台':'城市日常'}场景，自然光，干净背景，保留${p.facts.join('、')}，不添加未知性能。`,`围绕${p.name}实拍可见的${p.category==='美妆个护'?'瓶身、滴管和标签':'鞋面拼接、轮廓和结构'}做近景展示，柔和侧光表现层次，不推断未确认材质。`][index];
