 return `<div class="result-browser-bar"><div class="result-title"><h2>创作结果</h2><details class="review-guidance"><summary aria-label="交付审核说明" title="交付审核说明">${icon('shield')}</summary><div role="note">审核员批准并采用后可交付</div></details></div><div class="result-tabs" role="tablist" aria-label="结果媒体类型">${[['all','全部'],['image','图片'],['video','视频']].map(([id,label])=>`<button role="tab" aria-selected="${ui.tab===id}" class="${ui.tab===id?'active':''}" data-action="tab" data-id="${id}">${label}${ui.tab===id?`<small>${list.length}</small>`:''}</button>`).join('')}</div><details class="result-filter-menu ${filterLabel!=='筛选'?'has-filters':''}"><summary title="${esc(filterLabel)}">${icon('settings')}<span>${esc(filterLabel)}</span>${icon('down')}</summary><div class="result-filter-popover"><label class="parameter-field"><span>商品范围</span><select id="result-scope" aria-label="结果商品范围"><option value="current" ${ui.scope==='current'?'selected':''}>当前 SKU</option><option value="all" ${ui.scope==='all'?'selected':''}>全部 SKU</option></select></label><label class="parameter-field"><span>审核状态</span><select id="result-status" aria-label="审核状态筛选">${[['all','全部状态'],['pending','待审核'],['approved','已批准'],['rejected','已驳回']].map(([id,label])=>`<option value="${id}" ${ui.filter===id?'selected':''}>${label}</option>`).join('')}</select></label><button class="result-sort" data-action="sort" aria-label="切换排序">${icon('sort')}<span>${ui.sortDesc?'最新优先':'最早优先'}</span>${icon('down')}</button></div></details></div><div class="results-scroll" tabindex="0" role="region" aria-label="素材列表，可滚动"><div class="result-grid">${busy()?`<div class="loading-card"><div>${icon('refresh')}<p>正在将灵感变成作品</p><small>生成 → 保存 → 人工审核</small></div></div>`:''}${list.map(a=>assetCard(a,{compact:true})).join('')}${!list.length&&!busy()?empty(ui.scope==='current'&&!scoped.length?'为这件商品，开始第一份创作':'没有符合条件的素材',ui.scope==='current'&&!scoped.length?'写下创作描述，按当前商品实拍与所选风格开始生成。':'调整媒体类型或审核状态，查看其他结果。',!scoped.length&&assets().length?'查看全部 SKU':scoped.length?'清除筛选':'',!scoped.length?'all-skus':'clear-filter'):''}</div></div>${ui.selected.length?`<div class="results-bottom"><div class="selection-bar"><span>已选 ${ui.selected.length} 份</span><div class="row">${btn('并排对比','compare','sm','compare')}${ib('close','取消选择','clear-selection')}</div></div></div>`:''}`;
