function assetCard(a,options={}){
 const compact=options.compact===true;
 return `<article data-product="${a.product}" class="asset-card ${compact?'compact-asset':''} ${ui.selected.includes(a.id)?'selected':''}"><button class="asset-preview" data-action="asset-detail" data-id="${a.id}" aria-label="查看 ${esc(a.name)}">${artwork(a)}${a.media==='video'?`<span class="play-button">${icon('play')}</span><span class="video-duration">00:${a.duration||12}</span>`:''}</button><div class="asset-top"><span class="asset-type">${icon(a.media==='video'?'video':'image')}${purposeName(a.purpose)}</span><button class="asset-check ${ui.selected.includes(a.id)?'active':''}" data-action="select-asset" data-id="${a.id}" aria-label="选择 ${esc(a.name)}" aria-pressed="${ui.selected.includes(a.id)}">${icon('check')}</button></div><div class="asset-footer"><div class="asset-caption"><h4 title="${esc(a.name)}">${esc(a.name)}</h4>${compact&&ui.scope==='all'?`<span class="asset-product" title="${esc(product(a.product).name)} · ${esc(product(a.product).sku)}">${esc(product(a.product).sku)}</span>`:''}</div>${compact?'':`<div class="meta"><span>${a.media==='video'?`${a.duration||12}s · 1080P`:`${esc(a.snapshot?.quality||'2048 × 2048')} · PNG`}</span><span>${product(a.product).sku}</span></div>`}<div class="between">${statusBadge(a)}<span class="asset-version">${a.adopted?`<span class="asset-adopted">${icon('check')}已采用</span>`:''}<span>V${a.version}</span></span></div></div></article>`;}
function empty(title,sub,label,action){return `<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${sub}</p>${label?btn(label,action,'sm'):''}</div>`;}
function canvas(){
 const raw=task().nodes.filter(n=>ui.scope==='all'||n.draft.product===draft().product);
 ui.canvasOffsetX=Math.min(...raw.map(n=>n.x))-345;ui.canvasOffsetY=Math.min(...raw.map(n=>n.y))-70;
 const visible=raw.map(n=>({...n,x:n.x-ui.canvasOffsetX,y:n.y-ui.canvasOffsetY})),pids=[...new Set(visible.map(n=>n.draft.product))];
 const sources=[];
 for(const pid of pids){sources.push({id:`product:${pid}`,product:pid,kind:'product'});}
 for(const n of visible){for(const id of n.draft.references){if(sources.some(s=>s.id===id))continue;const a=canUse(assetFromRef(id))?assetFromRef(id):null,c=cases.find(c=>c.id===id&&!c.restricted);if(a)sources.push({id,product:a.product,kind:'asset',asset:a});else if(c)sources.push({id,kind:'case',case:c});}}
 const sourcePositions=sources.map((s,i)=>({...s,x:28,y:24+i*208}));
 const outputs=visible.flatMap(n=>assets().filter(a=>a.node===n.id&&a.product===n.draft.product).map((a,i)=>({asset:a,node:n,x:n.x,y:n.y+315+i*340})));
 const width=Math.max(660,...visible.map(n=>n.x+240),...outputs.map(o=>o.x+230)),height=Math.max(370,...visible.map(n=>n.y+310),...outputs.map(o=>o.y+350),sourcePositions.length*208+24);
 const outputNodes=outputs.map(({asset:a,x,y})=>`<article class="node canvas-output-node" data-output="${a.id}" style="left:${x}px;top:${y}px"><div class="node-header"><span class="row">${icon(a.media==='video'?'video':'image')}${a.media==='video'?'视频':'图片'}结果 · V${a.version}</span></div><button class="canvas-output-preview asset-preview" data-action="asset-detail" data-id="${a.id}" aria-label="查看 ${esc(a.name)}">${artwork(a)}${a.media==='video'?`<span class="play-button">${icon('play')}</span><span class="video-duration">00:${a.duration||12}</span>`:''}</button><div class="canvas-output-caption"><strong>${esc(a.name)}</strong>${statusBadge(a)}</div></article>`).join('');
 const nodes=visible.map(n=>{const p=product(n.draft.product);return `<div class="node ${n.id===ui.node&&ui.inspector?'active':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="node-header" data-drag="${n.id}"><span class="row">${icon(n.draft.media==='video'?'video':'spark')}${n.draft.media==='video'?'视频':'图片'}创作 · ${n.id.slice(1).padStart(2,'0')}</span>${ib('settings','编辑节点 '+n.id.slice(1),'edit-node').replace('data-action="edit-node"',`data-action="edit-node" data-id="${n.id}"`)}</div><div class="node-body"><button class="node-product" data-action="product-facts" data-id="${p.id}"><img src="${imageSrc(p.image)}" alt="${esc(p.name)}"><span><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></span></button><div class="between"><strong>${purposeName(n.draft.purpose)}</strong><span class="tag">${n.draft.count} 份</span></div><p class="node-prompt">${esc(n.draft.intent||n.draft.prompt).slice(0,54)}${(n.draft.intent||n.draft.prompt).length>54?'…':''}</p><div class="node-badge">${icon('link')}${1+n.draft.references.length} 份输入 · ${n.draft.ratio}</div><button class="btn primary sm wide" style="margin-top:12px" data-action="node-generate" data-id="${n.id}" ${busy()?'disabled':''}>${icon('spark')}${quickJobs.get(state.task)?.node===n.id?'生成中…':'生成'+(n.draft.media==='video'?'视频':'图片')}</button></div><div class="node-ports"><button class="port" data-action="connect-target" data-id="${n.id}">输入</button><button class="text-button" data-action="node-results" data-id="${n.id}">查看结果${icon('chevron')}</button></div></div>`}).join('');
 const sourceNodes=sourcePositions.map(s=>{const p=s.product?product(s.product):null,c=s.case,a=s.asset;return `<div class="node source-node" data-source="${s.id}" style="left:${s.x}px;top:${s.y}px"><div class="node-header"><span class="row">${icon(s.kind==='product'?'bag':'layers')}${s.kind==='product'?'商品实拍':s.kind==='asset'?'已批准素材':'案例参考'}</span><span class="tag">${s.kind==='product'?'事实依据':'表达参考'}</span></div><div class="node-body"><div class="source-node-image"><img src="${imageSrc(a?.image||p?.image||c.image)}" alt="${esc(p?.name||c.name)}"></div><strong>${esc(a?.name||p?.name||c.name)}</strong><p class="source-node-meta">${p?.sku||c.scope}</p></div><div class="node-ports"><span class="tiny muted">${s.kind==='product'?'绑定此 SKU':'可引用，不改商品事实'}</span><button class="port" data-action="connect-source" data-id="${s.id}">引用</button></div></div>`;}).join('');
 const wires=outputs.map(o=>`<path class="output-wire" d="M${o.node.x+105} ${o.node.y+280} C${o.node.x+105} ${o.y-20} ${o.x+105} ${o.y-20} ${o.x+105} ${o.y}"/>`).join('')+visible.map(n=>{const ids=[`product:${n.draft.product}`,...n.draft.references];return ids.map(id=>{const source=sourcePositions.find(s=>s.id===id);return source?`<path d="M238 ${source.y+125} C285 ${source.y+125} ${n.x-55} ${n.y+125} ${n.x} ${n.y+125}" ${source.kind==='product'?'':'stroke-dasharray="5 4"'}/>`:''}).join('')}).join('');
 return `<section class="canvas-workspace" aria-label="画布创作工作区"><div class="canvas-toolbar"><div class="row"><span class="canvas-status">${icon('canvas')}自由画布</span><button class="canvas-product-context" data-action="choose-product" title="切换画布商品">${esc(product(draft().product).name)}${icon('down')}</button><span class="canvas-node-count">${visible.length} 个节点</span></div><div class="row"><select id="canvas-scope" aria-label="画布商品范围"><option value="current" ${ui.scope==='current'?'selected':''}>当前 SKU</option><option value="all" ${ui.scope==='all'?'selected':''}>全部 SKU</option></select>${btn('添加节点','add-node','sm','plus')}</div></div><div class="canvas"><div class="canvas-viewport" tabindex="0" role="region" aria-label="可缩放的节点画布"><div class="canvas-world" style="width:${width*ui.zoom}px;height:${height*ui.zoom}px"><div class="canvas-stage" data-width="${width}" data-height="${height}" style="width:${width}px;height:${height}px;transform:scale(${ui.zoom})"><svg class="canvas-wire" viewBox="0 0 ${width} ${height}" style="width:${width}px;height:${height}px">${wires}</svg>${sourceNodes}${nodes}${outputNodes}</div></div></div><div class="canvas-hint">${icon('eye')}在画布节点内编辑生成参数，输入与结果都保留在画布中</div>${ui.connecting?`<div class="canvas-connecting">已选来源 · 点击目标节点「输入」${btn('取消','cancel-connect','sm')}</div>`:''}<div class="canvas-controls">${ib('minus','缩小画布','zoom-out')}<span id="canvas-zoom">${Math.round(ui.zoom*100)}%</span>${ib('plus','放大画布','zoom-in')}${ib('expand','适应画布','fit-canvas')}${ib('grid','自动整理画布','arrange')}</div>${ui.inspector?`<div class="canvas-inspector-scrim" data-action="dismiss-inspector"></div><aside class="canvas-node-inspector" ${matchMedia('(max-width:700px)').matches?'role="dialog" aria-modal="true"':''} aria-label="画布内节点设置">${composer(true)}</aside>`:''}</div><div class="canvas-bottom"><span>${icon('link')}连线仅添加输入引用，生成需单独确认</span>${ui.inspector?'<span>正在编辑节点 '+ui.node.slice(1).padStart(2,'0')+'</span>':'<span>节点内编辑与生成</span>'}</div></section>`;
}
function fitCanvas(){
 const viewport=$('.canvas-viewport'),stage=$('.canvas-stage');if(!viewport||!stage)return;
 ui.zoom=Math.max(.35,Math.min(1,(viewport.clientWidth-30)/Number(stage.dataset.width),(viewport.clientHeight-25)/Number(stage.dataset.height)));
 ui.fitPending=false;viewport.scrollLeft=0;viewport.scrollTop=0;updateCanvasZoom();
}
function updateCanvasZoom(){const stage=$('.canvas-stage'),world=$('.canvas-world');if(!stage||!world)return;stage.style.transform=`scale(${ui.zoom})`;world.style.width=Number(stage.dataset.width)*ui.zoom+'px';world.style.height=Number(stage.dataset.height)*ui.zoom+'px';$('#canvas-zoom').textContent=Math.round(ui.zoom*100)+'%';}
function productsPage(){
 const list=products.filter(p=>(ui.category==='all'||p.category===ui.category)&&`${p.name}${p.sku}${p.color}`.toLowerCase().includes(ui.search.trim().toLowerCase()));
 return heading('商品资料','管理商品实拍、规格与已确认信息。',btn('添加商品','new-product','','plus'))+
 `<div class="library-toolbar product-toolbar"><div class="search">${icon('search')}<input id="library-search" aria-label="搜索商品名称、SKU 或颜色" placeholder="搜索商品名称、SKU 或颜色" value="${esc(ui.search)}"></div><div class="filters" role="group" aria-label="商品分类">${[['all','全部商品'],['鞋服','鞋服'],['美妆个护','美妆个护']].map(([id,name])=>`<button class="filter ${ui.category===id?'active':''}" data-action="category" data-id="${id}" aria-pressed="${ui.category===id}">${name}</button>`).join('')}</div><span class="product-count" role="status" aria-live="polite">${list.length} 件商品</span></div>`+
 `<div class="library-grid product-grid">${list.map(p=>`<article class="library-card product-card" data-product="${p.id}" aria-label="${esc(p.name)}"><div class="image"><button data-action="product-facts" data-id="${p.id}" aria-label="查看 ${esc(p.name)}"><img src="${imageSrc(p.image)}" alt="${esc(p.name)}" decoding="async"></button></div><div class="body"><div class="product-title"><h3 title="${esc(p.name)}">${esc(p.name)}</h3><span class="product-confirmed" title="资料已确认；查看资料可核对依据">${icon('shield')}<span>已确认</span><span class="sr-only">商品资料</span></span></div><div class="product-identity"><p class="product-sku">${esc(p.sku)}</p><span class="product-category">${esc(p.category)}</span></div><p class="product-spec" title="${esc(p.color)} · ${esc(p.spec)}">${esc(p.color)} · ${esc(p.spec)}</p><div class="between product-actions"><button class="text-button" data-action="product-facts" data-id="${p.id}" aria-label="查看 ${esc(p.name)} 的商品资料">查看资料${icon('chevron')}</button><button class="btn sm" data-action="use-product" data-id="${p.id}" aria-label="用 ${esc(p.name)} 制作">用此商品制作${icon('arrow')}</button></div></div></article>`).join('')}${!list.length?empty('没有找到这个商品','尝试商品名称或 SKU，也可以清除筛选。','清除搜索','clear-search'):''}</div>`;
}
function libraryToolbar(placeholder,filters){return `<div class="library-toolbar"><div class="search">${icon('search')}<input id="library-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(ui.search)}"></div><div class="filters">${filters.map(([id,n])=>`<button class="filter ${ui.category===id?'active':''}" data-action="category" data-id="${id}">${n}</button>`).join('')}</div></div>`;}
function caseReferenceButton(c,primary=false){
 const added=draft().references.includes(c.id);
 return `<button class="btn ${primary?'primary':'sm'} case-reference ${added?'is-added':''}" data-action="${added?'remove-case':'add-case'}" data-id="${c.id}" ${c.restricted?'disabled aria-describedby="case-restriction-'+(primary?'preview-':'')+c.id+'"':`aria-pressed="${added}" aria-label="${added?'移除参考':'添加参考'}：${esc(c.name)}"`} title="${c.restricted?'授权待确认，暂不能引用':added?'点击移除当前创作中的参考':'添加到当前商品创作'}">${icon(c.restricted?'lock':added?'check':'plus')}${c.restricted?'暂不可引用':added?'已添加':'添加参考'}</button>`;
}
function casesPage(){
 const list=filterReferenceEntries(cases,{search:ui.search,category:ui.category,media:ui.caseMedia});
 return heading('案例灵感','挑选构图、光线与风格，作为当前创作的参考。')+
 `<div class="case-toolbar"><div class="search">${icon('search')}<input id="library-search" aria-label="搜索案例名称、场景或风格" placeholder="搜索案例名称、场景或风格" value="${esc(ui.search)}"></div><div class="filters" role="group" aria-label="案例媒体类型">${[['all','全部'],['image','图片'],['video','视频']].map(([id,name])=>`<button class="filter ${ui.caseMedia===id?'active':''}" data-action="case-media" data-id="${id}" aria-pressed="${ui.caseMedia===id}">${name}</button>`).join('')}</div><select id="case-category" aria-label="案例品类"><option value="all" ${ui.category==='all'?'selected':''}>全部品类</option>${['鞋服','美妆个护'].map(name=>`<option ${ui.category===name?'selected':''}>${name}</option>`).join('')}</select><span class="case-count" role="status" aria-live="polite">${list.length} 个案例</span></div>`+
 `<div class="library-grid case-grid">${list.map(c=>`<article class="library-card case-card" data-case="${c.id}"><div class="image"><button data-action="case-preview" data-id="${c.id}" aria-label="${c.media==='video'?'查看视频分镜':'预览案例'}：${esc(c.name)}"><img src="${imageSrc(c.image)}" alt="${esc(c.name)}" decoding="async"></button>${c.media==='video'?`<span class="case-storyboard-label">${icon('layers')}视频分镜</span>`:''}</div><div class="body"><h3 title="${esc(c.name)}">${esc(c.name)}</h3><p class="case-features" title="${esc(c.features)}">${esc(c.features)}</p><div class="case-actions"><span class="case-source">${c.category} · ${c.restricted?'外部':'内部'}${c.restricted?`<small id="case-restriction-${c.id}">仅供浏览 · 授权待确认</small>`:''}</span>${caseReferenceButton(c)}</div></div></article>`).join('')}${!list.length?empty('暂时没有匹配的灵感','换个关键词，或清除筛选查看全部案例。','清除筛选','clear-search'):''}</div>`;
}
function previewCase(id){
 const c=cases.find(c=>c.id===id);if(!c)return;const fromPicker=!!$('#case-picker-search')||$('.case-preview-dialog')?.dataset.picker==='true';
 const shots=c.media==='video'?`<div class="case-shot-list" aria-label="视频分镜说明">${[['01','0–4 秒','全貌定场'],['02','4–8 秒','过渡细节'],['03','8–12 秒','回到全貌']].map(([n,time,text])=>`<div><span>${n} · ${time}</span><strong>${text}</strong></div>`).join('')}</div><p class="case-preview-note">视频分镜示例，当前提供关键帧与分镜说明。</p>`:'';
 openModal(c.name,`<div class="case-preview-image"><img src="${imageSrc(c.image)}" alt="${esc(c.name)}"></div><p class="case-preview-meta">${c.category} · ${c.tag} · ${c.restricted?'外部灵感':'内部案例'}</p><p class="case-preview-style">${esc(c.style)}</p>${shots}${c.restricted?`<p class="case-restriction" id="case-restriction-preview-${c.id}">${icon('lock')}仅供浏览：使用授权待确认，暂不能引用至创作。</p>`:''}<p class="case-preview-note">引用至：${esc(product(draft().product).name)} · ${purposeName(draft().purpose)}。仅借鉴表达，商品外观以当前商品实拍为准。</p>`,(fromPicker?btn('返回案例列表','case-picker-back'):btn('关闭','close-modal'))+(draft().references.includes(c.id)&&!fromPicker?btn('返回创作','case-return'):'' )+caseReferenceButton(c,true));
 $('.overlay .modal').classList.add('case-preview-dialog');$('.overlay .modal').dataset.casePreview=c.id;$('.overlay .modal').dataset.picker=String(fromPicker);
}
function reviewIssue(a){return a.status==='rejected'?(a.reason||'请查看返工意见。'):a.status==='approved'?'已人工批准':a.historyNote?'历史备注：'+a.historyNote:'等待人工审核';}
function assetSpecs(a){return a.media==='video'?`${a.duration||12} 秒 · ${a.snapshot?.quality||'1080P'} · ${a.purpose==='clip'?'关键帧示例':'分镜示例'}`:`${a.snapshot?.quality||'2048 × 2048'} · PNG`;}
function reviewRecord(a){return a.status==='approved'?`${a.reviewerName||'历史审核人'} · ${a.reviewedAt||'时间未记录'} · 批准`:a.status==='rejected'?`${a.reviewerName||'历史审核人'} · 已驳回`:'等待人工审核';}
function assetNote(a){return a.status==='rejected'?`<div class="review-problem"><strong>人工已驳回</strong><p>${esc(a.reason||'请查看返工意见。')}</p></div>`:a.historyNote?`<p class="review-history-note">历史备注（供人工核对）：${esc(a.historyNote)}</p>`:'';}
function reviewPage(){
 const counts=Object.fromEntries(['all',...Object.keys(statusNames)].map(key=>[key,key==='all'?assets().length:assets().filter(a=>a.status===key).length]));
 const list=assets().filter(a=>ui.reviewFilter==='all'||(a.status===ui.reviewFilter));
 return heading('审核中心','核对商品一致性，完成素材审核。')+`<div class="review-filters" role="group" aria-label="审核状态">${[['pending','待审核'],['rejected','已驳回'],['approved','已批准'],['all','全部']].map(([id,name])=>`<button id="review-filter-${id}" class="filter ${ui.reviewFilter===id?'active':''}" data-action="review-filter" data-id="${id}" aria-pressed="${ui.reviewFilter===id}">${name}<span>${counts[id]}</span></button>`).join('')}</div><div class="review-list" role="table" aria-label="当前任务素材审核列表"><div role="rowgroup" class="review-list-head"><div class="review-row" role="row">${['素材 / 商品','当前状态','审核说明 / 处理原因','版本 / 生成时间','操作'].map(t=>`<span role="columnheader">${t}</span>`).join('')}</div></div><div role="rowgroup">${list.map(a=>`<div class="review-row" role="row" data-review="${a.id}"><div class="review-item" role="cell"><button class="review-thumb" data-action="asset-detail" data-id="${a.id}" aria-label="查看 ${esc(a.name)} V${a.version}"><img src="${imageSrc(a.image)}" alt="${esc(a.name)}"></button><div><h3 title="${esc(a.name)}">${esc(a.name)}</h3><p>${esc(product(a.product).sku)}</p>${a.media==='video'?'<small>视频分镜 · '+(a.duration||12)+' 秒</small>':''}</div></div><div class="review-row-status" role="cell">${statusBadge(a)}</div><p class="review-issue ${a.status==='rejected'?'has-issue':''}" role="cell" title="${esc(reviewIssue(a))}">${esc(reviewIssue(a))}</p><div class="review-time" role="cell"><span>V${a.version}</span><small>生成于 ${esc(a.created)}</small></div><div class="review-row-action" role="cell"><button class="btn sm ${a.status==='pending'?'primary':''}" data-action="asset-detail" data-id="${a.id}">${a.status==='pending'?'开始审核':a.status==='rejected'?'查看问题':'查看详情'}${icon('chevron')}</button></div></div>`).join('')}</div></div>${!list.length?empty(ui.reviewFilter==='pending'?'当前没有待审核素材':'这个状态下暂无素材',ui.reviewFilter==='pending'?'新素材保存后会出现在这里。':'可切换其他状态查看已有素材。',ui.reviewFilter==='all'?'':'查看全部',ui.reviewFilter==='all'?'':'review-filter').replace('data-action="review-filter"','data-action="review-filter" data-id="all"'):''}`;
}
function assetsPage(){return delivery.renderPage();}
function updateCanvasAccessibility(){
 const canvasSheet=ui.page==='studio'&&ui.view==='canvas'&&!!$('#overlay-root .overlay');
 const inspectorSheet=ui.page==='studio'&&ui.view==='canvas'&&ui.inspector&&matchMedia('(max-width:700px)').matches;
 const inspector=$('.canvas-node-inspector');
 if(inspector){inspector.setAttribute('role',inspectorSheet?'dialog':'complementary');if(inspectorSheet)inspector.setAttribute('aria-modal','true');else inspector.removeAttribute('aria-modal');inspector.inert=canvasSheet;}
 for(const el of $$('.canvas-toolbar,.canvas-bottom,.canvas-viewport,.canvas-controls,.canvas-hint,.canvas-connecting'))el.inert=canvasSheet||inspectorSheet;
 if(ui.view==='canvas')for(const el of $$('.studio-taskbar,.sidebar,.topbar'))el.inert=canvasSheet||inspectorSheet;
}
function updateSidebarAccessibility(){
 const mobile=matchMedia('(max-width:700px)').matches, drawer=mobile&&ui.mobile;
 const nav=$('.sidebar');if(!nav)return;
 if(mobile){nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');}
 else{nav.removeAttribute('role');nav.removeAttribute('aria-modal');}
 nav.inert=(mobile&&!drawer)||nav.inert;
 const background=$('.content-shell');if(background)background.inert=drawer;
 if(drawer)document.body.style.overflow='hidden';
}
