 const comparison=`<div class="review-comparison" data-zoom=""><figure data-pane="result"><figcaption>生成结果 · V${a.version}${a.media==='video'?' · 关键帧':''}</figcaption><button class="asset-preview review-result" data-action="review-zoom" data-id="result" aria-label="放大或收起生成结果" aria-pressed="false">${artwork(a)}<span class="review-zoom-label">放大</span></button></figure><figure data-pane="source"><figcaption>商品实拍 · ${esc(p.sku)}</figcaption><button class="review-source" data-action="review-zoom" data-id="source" aria-label="放大或收起商品实拍" aria-pressed="false"><img src="${imageSrc(p.image)}" alt="${esc(p.name)} · 商品实拍"><span class="review-zoom-label">放大</span></button></figure></div>`;
