 let buttons=canReview(a)?`<button class="btn" data-action="reject" data-id="${id}">驳回返工</button><button class="btn primary" data-action="approve" data-id="${id}">${icon('check')}批准此版本</button>`:a.status==='approved'?`<button class="btn" data-action="adopt" data-id="${id}" ${a.adopted||a.purpose==='clip'?'disabled':''}>${a.purpose==='clip'?'片段不计成片交付':a.adopted?'已采用至交付':'采用至交付'}</button>`:`<button class="btn" data-action="rework" data-id="${id}">${icon('refresh')}调整并返工</button>`;
 openModal(a.status==='pending'?'素材审核':'素材详情',body,`<span class="review-footer-note">${a.status==='pending'?'审核决定仅绑定当前版本':a.status==='approved'?'此版本已批准':'返工将保留原版本与意见'}</span><div class="review-footer-actions">${buttons}${a.status==='approved'&&a.adopted&&a.purpose!=='clip'?btn('查看交付清单','flow-delivery',next?'':'primary','arrow'):''}${a.status!=='pending'&&next?`<button class="btn primary" data-action="review-next">下一份待审${icon('arrow')}</button>`:''}</div>`,{wide:true});
