function pickerCases(){return filterReferenceEntries(cases,casePicker);}
function browseCases(){const list=pickerCases();openModal('给创作找一点灵感',`<div class="note" style="margin-bottom:12px">引用只影响构图、光线和表达；商品外观仍以当前 SKU 实拍为准。</div><div class="case-picker-toolbar"><label class="search">${icon('search')}<input id="case-picker-search" aria-label="搜索案例名称、场景或风格" placeholder="搜索案例名称、场景或风格" value="${esc(casePicker.search)}"></label><select id="case-picker-category" aria-label="筛选案例品类"><option value="all" ${casePicker.category==='all'?'selected':''}>全部品类</option>${['鞋服','美妆个护'].map(name=>`<option value="${name}" ${casePicker.category===name?'selected':''}>${name}</option>`).join('')}</select><select id="case-picker-media" aria-label="筛选案例媒体"><option value="all" ${casePicker.media==='all'?'selected':''}>全部媒体</option><option value="image" ${casePicker.media==='image'?'selected':''}>图片</option><option value="video" ${casePicker.media==='video'?'selected':''}>视频</option></select></div><p class="case-picker-count" role="status">找到 ${list.length} 个案例 · 授权待确认的案例仅可预览</p>${list.map(c=>`<div class="choice-card case-picker-card"><button class="case-picker-preview" data-action="case-preview" data-id="${c.id}" aria-label="预览案例：${esc(c.name)}"><img src="${imageSrc(c.image)}" alt="${esc(c.name)}"></button><span class="grow"><strong>${esc(c.name)}</strong><p>${esc(c.category)} · ${esc(c.tag)}${c.media==='video'&&c.tag!=='视频分镜'?' · 视频分镜':''}</p><p>${esc(c.scope)}</p></span>${caseReferenceButton(c)}</div>`).join('')||'<p class="muted">没有匹配的案例，请调整搜索或筛选。</p>'}`,btn('完成','close-modal'),{subtitle:'搜索、筛选并预览团队案例；添加后保留当前模板与数量。'});}
function referenceAnalysis(){const ref=cases.find(c=>draft().references.includes(c.id))||cases.find(c=>c.category===product(draft().product).category&&!c.restricted);openModal('解析参考表达',`<div class="analysis-grid"><img src="${imageSrc(ref.image)}" alt="参考案例 ${ref.name}"><div><div class="analysis-line"><strong>构图</strong>主体居中略偏右，四周留白</div><div class="analysis-line"><strong>光线与色调</strong>柔和侧光、低饱和背景，清晰表达商品轮廓</div><div class="analysis-line"><strong>来源</strong>${ref.name} · ${ref.scope}</div></div></div><label for="analysis-prompt">适用于当前 SKU 的表达建议 · 可编辑</label><textarea id="analysis-prompt">以${product(draft().product).name}实拍为主体。${ref.style}保持当前商品的${product(draft().product).facts.join('、')}，不引入参考中的商品、标识或未知卖点。</textarea><label class="checkbox-label"><input type="checkbox" id="also-reference" ${draft().references.includes(ref.id)?'checked':''}>同时将此案例图作为生成输入引用</label><div class="note" style="margin-top:15px">此处展示预设解析示例，未调用识图服务；不是原始提示词还原。应用只更新草稿，不会自动生成。</div>`,btn('取消','close-modal')+`<button class="btn primary" data-action="apply-analysis" data-id="${ref.id}">应用到当前草稿</button>`);}
function showGeneration(){
 if(busy())return;if(!draft().prompt.trim()){ui.promptOpen=true;render();toast('请填写完整提示词，或恢复公司默认配置。');$('#prompt')?.focus();return;}
 company.requireRight('create');const d=draft(),p=product(d.product),problem=draftProblem(d);if(problem){toast(problem);return;}const needsStoryboard=production.needsStoryboard(d);if(needsStoryboard&&!d.shots)d.shots=production.defaultShots(d);
 const shots=needsStoryboard?`<div class="between"><label>视频分镜 · 总长 ${d.duration} 秒</label><button class="btn sm" data-action="shots-edit" data-id="quick">编辑分镜</button></div>${requirements.summary(d)}<label class="checkbox-label"><input id="confirm-shots" type="checkbox" ${production.confirmed(d)?'checked':''}>已确认当前 SKU 的分镜、商品事实与视频总时长</label>`:'';
 openModal(needsStoryboard?'确认带货成片':'准备好，开始这次创作',`<div class="choice-card active" style="cursor:default"><img src="${imageSrc(p.image)}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><p>${esc(p.sku)} · ${esc(p.color)}</p></div></div><div class="plan-list"><div class="plan-item"><span>本次输出</span><strong>${purposeName(d.purpose)} × ${d.count}</strong></div><div class="plan-item"><span>画面规格</span><span>${d.ratio} · ${d.media==='video'?`1080P · ${d.duration} 秒`:d.quality+' px'}</span></div><div class="plan-item"><span>生成依据</span><span>${new Set([p.image,p.source]).size+d.uploads.length} 份商品实拍 · ${d.references.length} 份表达参考</span></div><div class="plan-item"><span>本次模板</span><span>${esc(d.template)} · V${d.templateVersion}</span></div></div>${shots}<details style="font-size:11px;color:#869877;margin:16px 0"><summary style="cursor:pointer">查看生成输入快照</summary><p style="margin-top:10px">${esc(combinedPrompt(d))}</p></details><div class="note">生成并保存后交由审核员处理。${d.purpose==='clip'?'片段结果不计入带货成片交付。':''}</div><div class="field-error" id="generation-error"></div>`,btn('再调整一下','close-modal')+btn(`确认创作 ${d.count} ${d.media==='video'?'条':'张'}`,'confirm-generate','primary','spark'));
}
function generate(){
 company.requireRight('create');const problem=draftProblem(draft());if(problem){toast(problem);return;}if(busy())return;const needsStoryboard=production.needsStoryboard(draft());if(needsStoryboard&&!$('#confirm-shots')?.checked){$('#generation-error').textContent='请先确认分镜、商品事实与总时长。';return;}
 if(needsStoryboard){const p=production.validateShots(draft());if(p){$('#generation-error').textContent=p;return;}production.confirm(draft());}
 production.ensurePurpose(task(),draft().product,draft().purpose);
 const snapshot=company.freeze(JSON.parse(JSON.stringify(draft()))),tid=task().id,nodeId=ui.node,p=product(snapshot.product),parent=snapshot.reworkParent;snapshot.prompt=combinedPrompt(snapshot);quickJobs.set(tid,{node:nodeId});closeModal();ui.page='studio';if(ui.view!=='canvas')ui.view='page';ui.scope='current';ui.selected=[];ui.filter='all';ui.tab='all';render();
 setTimeout(()=>{const t=state.tasks.find(t=>t.id===tid);if(!t){quickJobs.delete(tid);return;}const stamp=Date.now();for(let i=0;i<snapshot.count;i++){const result={companyId:t.companyId,creatorId:snapshot.creatorId,creatorName:snapshot.creatorName,scene:snapshot.template,id:`gen${stamp}-${i}`,product:p.id,name:`${p.custom?p.name:p.category==='美妆个护'?'自然植感':'城市轻行'} · ${purposeName(snapshot.purpose)} ${i+1}`,purpose:snapshot.purpose,image:i%2===0?p.image:p.source,style:snapshot.media==='video'?'plain':snapshot.purpose==='detail'?'detail':i%2===0?'minimal':'editorial',status:'pending',version:parent?(t.assets.find(a=>a.id===parent)?.version||1)+1:1,parent,media:snapshot.media,duration:+snapshot.duration,created:'刚刚',node:nodeId,snapshot,adopted:false,subtitle:p.category==='美妆个护'?'自然，有自己的光':'轻一点，自在一点'};t.assets.unshift(result);}quickJobs.delete(tid);if(state.task===tid&&ui.page==='studio'&&ui.view==='canvas'){ui.fitPending=true;ui.inspector=false;}persist();render();toast(`${state.task===tid?'':t.name+'：'}${snapshot.count} 份素材已生成并保存，已提交人工审核。`);},1600);
}
function rework(id){
 const a=assets().find(a=>a.id===id);if(!a)return;syncDraft();
 const d={...freshDraft(a.product),...(a.snapshot||{}),purpose:a.purpose,media:a.media,count:1,intent:'',reworkParent:a.id,prompt:`${a.snapshot?.prompt||basePrompt(product(a.product))}\n返工要求：${a.reason||'在保持当前商品事实的前提下调整构图和光线。'}`};
 const n={id:'g'+(Math.max(0,...task().nodes.map(n=>Number(n.id.slice(1))))+1),x:Math.max(345,...task().nodes.map(n=>n.x+285)),y:70,draft:d};task().nodes.push(n);ui.node=n.id;task().draft=JSON.parse(JSON.stringify(d));
 ui.page='studio';if(ui.view==='canvas'){ui.inspector=true;ui.focusInspector=true;ui.fitPending=true;}else ui.view='page';ui.scope='current';ui.filter='all';ui.tab='all';ui.selected=[];ui.promptOpen=true;syncDraft();closeModal();render();toast(`已带入 V${a.version} 的资料与意见，仅重做此份输出。`);
}
function reject(id){company.requireRight('review');const a=assets().find(a=>a.id===id);if(!canReview(a))return;openModal('记录返工意见',`<p class="muted tiny">${esc(a.name)} · V${a.version}</p><label for="reject-reason">驳回原因 <span style="color:var(--danger)">*</span></label><textarea id="reject-reason" placeholder="请说明具体问题，例如：主体构图过满，需增加右侧留白。" data-autofocus></textarea><div id="reject-error" class="field-error"></div><div class="note">意见绑定此确切版本；返工后生成新版本，重新提交人工审核。</div>`,(ui.page==='review'?`<button class="btn" data-action="review-cancel-reject" data-id="${id}">返回审核</button>`:btn('取消','close-modal'))+`<button class="btn danger" data-action="confirm-reject" data-id="${id}">确认驳回</button>`);}
