// Small, dependency-free ZIP writer (stored entries, UTF-8 filenames).
const encoder=new TextEncoder();
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function zipBlob(files){const chunks=[],central=[];let offset=0;for(const f of files){const name=encoder.encode(f.name),data=f.data,crc=crc32(data);let local=new Uint8Array(30+name.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);local.set(name,30);chunks.push(local,data);let c=new Uint8Array(46+name.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x0800,true);w.setUint32(16,crc,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,name.length,true);w.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=local.length+data.length;}const end=new Uint8Array(22),e=new DataView(end.buffer),centralSize=central.reduce((n,c)=>n+c.length,0);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
function imageDimensions(a){const d=a.snapshot||{},side=parseInt(d.quality)||2048,[w,h]=(d.ratio||'1:1').split(':').map(Number);return w>=h?[side,Math.round(side*h/w)]:[Math.round(side*w/h),side];}
async function renderImage(a){const img=new Image();img.src=imageSrc(a.image);await img.decode();const c=document.createElement('canvas');[c.width,c.height]=imageDimensions(a);const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#e7e9e0';ctx.fillRect(0,0,w,h);const scale=Math.max(w/img.width,h/img.height)*(a.style==='detail'?1.75:1);ctx.drawImage(img,(w-img.width*scale)/2,(h-img.height*scale)/2,img.width*scale,img.height*scale);ctx.fillStyle='#46503f';if(a.style==='minimal'){ctx.font=`${w*.018}px sans-serif`;ctx.fillText('THE EVERYDAY COLLECTION',w*.06,h*.08);ctx.font=`${w*.038}px sans-serif`;ctx.fillText(a.subtitle||'轻一点，自在一点',w*.06,h*.91);}if(a.style==='editorial'){ctx.font=`bold ${w*.10}px sans-serif`;['MOVE','YOUR','EVERYDAY.'].forEach((v,i)=>ctx.fillText(v,w*.06,h*.16+i*w*.095));}return new Uint8Array(await new Promise((resolve,reject)=>c.toBlob(async blob=>{if(!blob)return reject(new Error('图片导出失败'));resolve(await blob.arrayBuffer());},'image/png')));}
function validateExport(snapshot){company.requireRight('download');if(!snapshot||snapshot.taskId!==task().id||snapshot.planRevision!==(task().planRevision||0))throw new Error('任务或交付要求已变化，请重新核对导出清单。');const rows=delivery.slots();for(const old of snapshot.rows){const now=rows.find(r=>r.key===old.key);if(!now||now.asset?.id!==old.asset?.id||old.asset&&(!canUse(now.asset)||!production.matches(now.asset,now)))throw new Error('交付采用或审核状态已变化，请重新核对。');}}
async function downloadPackage(){
 const snapshot=deliveryExportSnapshot,button=$('[data-action=download-package]');if(button?.disabled)return;
 try{
  validateExport(snapshot);if(button){button.disabled=true;button.textContent='正在整理文件…';}
  const safe=s=>String(s).replace(/[\\/:*?"<>|\x00-\x1f]/g,'-').slice(0,80);
  const items=snapshot.rows.map(row=>{const a=row.asset,sku=product(row.product).sku,filename=a?`${safe(sku)}/${safe(row.module)}-${row.index+1}-${safe(a.id)}-V${a.version}${a.media==='image'?'.png':'-分镜说明.txt'}`:null;return{slot:row.key,sku,product:product(row.product).name,module:row.module,position:row.index+1,purpose:purposeName(row.purpose),purposeKey:row.purpose,ratio:row.ratio,quality:row.quality,status:a?'已采用':'缺口',filename,asset:a?{id:a.id,name:a.name,version:a.version,media:a.media,creator:a.creatorName,template:a.snapshot?.template,templateVersion:a.snapshot?.templateVersion,references:a.snapshot?.referenceSnapshots||[],exportFormat:a.media==='image'?'PNG':'TXT',...(a.media==='image'?{width:imageDimensions(a)[0],height:imageDimensions(a)[1]}:{duration:a.duration||12,shots:a.snapshot?.shots||production.defaultShots({duration:a.duration||12}),videoFileIncluded:false})}:null};});
  const files=[{name:'交付清单.json',data:encoder.encode(JSON.stringify({task:snapshot.name,planRevision:snapshot.planRevision,type:items.some(r=>!r.asset)?'部分交付':'完整交付',notice:'本地 UI 原型演示包。图片按所选比例、最大边清晰度输出示例；视频仅含已确认分镜说明。',items},null,2))},{name:'使用说明.txt',data:encoder.encode('造物 Studio UI 原型演示包。\n用于界面评审，非真实模型生成。图片来源见原型 assets/来源说明.md。\n缺失位置列入清单；视频仅提供分镜 TXT，不包含真实成片。')}];
  for(let i=0;i<snapshot.rows.length;i++){const a=snapshot.rows[i].asset;if(!a)continue;if(a.media==='image')files.push({name:items[i].filename,data:await renderImage(a)});else{let at=0;const text=items[i].asset.shots.map((s,i)=>{const start=at;at+=+s.duration;return `镜头 ${i+1} · ${start}–${at} 秒：${s.visual}${s.copy?'\n文案：'+s.copy:''}`;}).join('\n');files.push({name:items[i].filename,data:encoder.encode(`分镜原型，无真实成片。\n${text}`)});}}
  validateExport(snapshot);const blob=zipBlob(files),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`造物-${safe(snapshot.name)}-演示交付包.zip`;link.click();company.audit('导出交付包',task().id,`${items.filter(x=>x.asset).length}/${items.length} 个位置`);persist();setTimeout(()=>URL.revokeObjectURL(url),2000);closeModal();toast('演示 ZIP 已导出，包含采用版本、规格、分镜和缺口。');
 }catch(error){if(button){button.disabled=false;button.textContent='重试下载';}toast(error.message);}
}
function activity(){openModal('任务动态',`<div class="help-steps"><div class="help-step"><div><h3>${assets().filter(a=>a.status==='pending').length} 份素材等待人工审核</h3><p>生成结果已保存，前往审核中心对照实拍，决定批准或驳回。</p></div></div><div class="help-step"><div><h3>${assets().filter(a=>a.status==='approved').length} 份已批准素材</h3><p>采用至 SKU 交付位置，即可整理并下载演示交付包。</p></div></div><div class="help-step"><div><h3>${assets().filter(a=>a.status==='rejected').length} 份素材需要处理</h3><p>查看审核员的驳回原因，调整后只返工问题输出。</p></div></div></div>`,btn('关闭','close-modal')+btn('前往审核中心','go-review','primary'));}
function help(){openModal('从实拍，到一份好交付',`<div class="help-steps">${[['新建制作，选好商品','点击新建制作，选择或添加商品，再选择主图、详情素材或带货视频。名称自动生成，可稍后修改。'],['把方向讲清楚','选用途与快捷词，或引用团队案例。快捷、批量与画布可随时切换，草稿自动保留。批量图片与视频分开配置，一键提交多个生成项。'],['创作，再认真看一眼','素材保存后由审核员对照实拍，决定批准或驳回。'],['让好作品成为团队资产','批准并采用至交付清单，下载包含版本、示例图片与缺口说明的 ZIP。']].map(([t,p])=>`<div class="help-step"><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><details class="help-rules"><summary>创作与交付规则</summary><ul><li>商品颜色、轮廓、标签和结构以当前 SKU 的实拍及已确认资料为准，不增加无依据的卖点。</li><li>模板与参考用于构图、光线和风格表达，不替换商品事实；当前参数修改不覆盖公司默认模板。</li><li>素材保存后提交人工审核。返工保留原版本及原因，新版本重新提交审核。</li><li>按商品、模块、数量和规格，为每个交付位置采用一个匹配的批准版本；部分导出须列明缺口。</li></ul></details><div class="note" style="margin-top:18px">这是独立高保真 UI 原型。AI 生成、参考解析为本地模拟；审核决定仅保存于当前浏览器；暂无真实账号、付费调用和后台生产服务。数据保存在此浏览器；商品库实拍在本机保存，创作区临时补充图仅保留当前会话。</div>`,btn('清除演示修改','reset-demo')+btn('开始体验','close-modal','primary'));}
